import AVFoundation
import Foundation

/// Short cartoon sound effects (generated by design/make_sounds.py).
/// Uses the "ambient" audio session: mixes with music and respects the silent switch.
final class SoundFX {
    static let shared = SoundFX()

    enum Sound: String, CaseIterable {
        case pop, chime, fanfare, poof
    }

    /// Settings toggle (stored in UserDefaults, read with @AppStorage("soundOn")).
    static let settingKey = "soundOn"

    private var players: [Sound: AVAudioPlayer] = [:]

    private init() {
        try? AVAudioSession.sharedInstance().setCategory(.ambient, options: [.mixWithOthers])
        for sound in Sound.allCases {
            guard let url = Bundle.main.url(forResource: sound.rawValue, withExtension: "wav"),
                  let player = try? AVAudioPlayer(contentsOf: url) else { continue }
            player.enableRate = true
            player.prepareToPlay()
            players[sound] = player
        }
    }

    private var enabled: Bool {
        UserDefaults.standard.object(forKey: SoundFX.settingKey) as? Bool ?? true
    }

    /// `pitch` 0.5...2.0 — each character gets its own pitch for the pop.
    func play(_ sound: Sound, pitch: Float = 1.0) {
        guard enabled, let player = players[sound] else { return }
        player.rate = pitch
        player.currentTime = 0
        player.play()
    }
}

extension MascotKind {
    /// Each character "pops" in its own voice.
    var popPitch: Float {
        switch self {
        case .drop: return 1.0
        case .apple: return 0.85
        case .sprout: return 1.15
        case .sun: return 1.3
        case .flame: return 0.75
        case .blob: return 0.95
        }
    }
}
